import subprocess, re, json, glob
repo="/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
branches=["rachel","monica","phoebe","joey","chandler","ross"]
def git(*a):
    return subprocess.run(["git","-C",repo]+list(a),capture_output=True,text=True).stdout
out={}
for b in branches:
    items=[]
    for line in git("log","--format=%H %cI","origin/friend/"+b).strip().split("\n"):
        sha,t=line.split(" ",1)
        msg=git("show","-s","--format=%B",sha)
        paras=msg.split("\n\n")
        hdr=None
        for p in paras:
            lines=[l.strip() for l in p.strip().split("\n")]
            if lines and lines[0]=="Friend-Message: 1" and any(l.startswith("Speaker:") for l in lines) and any(l.startswith("Episode:") for l in lines):
                hdr=lines; break
        if not hdr: continue
        ep=[l for l in hdr if l.startswith("Episode:")][0].split(":",1)[1].strip()
        rt=[l for l in hdr if l.startswith("Reply-To:")][0].split(":",1)[1].strip()
        idx=paras.index("\n".join(hdr))
        body="\n\n".join(paras[idx+1:]).strip()
        items.append(dict(sha=sha,time=t,ep=ep,rt=rt,body=body,branch=b))
    out[b]=items
json.dump(out,open("/tmp/fm.json","w"))
published={}
for f in sorted(glob.glob(repo+"/S*/E*.md")):
    for m in re.finditer(r"Source: (friend/\w+) @ ([0-9a-f]{40})", open(f).read()):
        published[m.group(2)]=f
miss={}
for b,items in out.items():
    m=[i for i in items if i["sha"] not in published]
    miss[b]=m
    print(b,len(items),"missing",len(m))
json.dump(miss,open("/tmp/missing.json","w"))
print("=== all missing detail ===")
for b in out:
    for it in sorted(miss[b],key=lambda x:(x["time"],x["sha"])):
        print(b,it["sha"],it["time"],it["ep"],it["rt"][:12],repr(it["body"][:70]))
EOF
